@app.route('/login')
def login_page():
    return render_template('login.html', current_user=None)

@app.route('/auth/callback')
def auth_callback():
    """Receives JWT via query param, sets Flask session, redirects to dashboard."""
    from flask import session as flask_session
    from flask_jwt_extended import decode_token
    token = request.args.get('token', '')
    role = request.args.get('role', '')
    if not token:
        return redirect('/login')
    try:
        decoded = decode_token(token)
        uid = decoded.get('sub')
        claims = decoded
        flask_session['user_id'] = int(uid)
        flask_session['user_role'] = claims.get('role', role)
        flask_session['user_full_name'] = claims.get('full_name', '')
        flask_session.permanent = True
    except Exception:
        return redirect('/login')
    role = flask_session['user_role']
    if role == 'asha':
        return redirect('/asha')
    elif role == 'doctor':
        return redirect('/doctor')
    elif role == 'patient':
        return redirect('/patient')
    return redirect('/')

