    role = request.args.get('role', '')
    if not token:
        return redirect('/login')
    try:
        decoded = decode_token(token)
        uid = decoded.get('sub')
        claims = decoded
        flask_session['user_id'] = int(uid)
        flask_session['user_role'] = claims.get('role', role)
        flask_session['user_full_name'] = claims.get('full_name', '')
        flask_session.permanent = True
    except Exception:
        return redirect('/login')
    role = flask_session['user_role']
    if role == 'asha':
        return redirect('/asha')
    elif role == 'doctor':
        return redirect('/doctor')
    elif role == 'patient':
        return redirect('/patient')
    return redirect('/')

