{% extends "base.html" %}
{% block title %}Clinical Memory{% endblock %}
{% block page_title %}<i class="fa-solid fa-timeline me-2" style="color:#0d9488"></i>Longitudinal Intelligence Timeline{% endblock %}

{% block head %}
<style>
  /* ── Page chrome ───────────────────────────────────────────────── */
  .pcm-hero {
    background: linear-gradient(135deg, #0f766e 0%, #1d6fa4 100%);
    border-radius: 14px; padding: 1.5rem 2rem; color: #fff;
    display: flex; align-items: center; gap: 2rem; flex-wrap: wrap;
    margin-bottom: 1.5rem; position: relative; overflow: hidden;
  }
  .pcm-hero::after {
    content: 'PCM'; position: absolute; right: 1.5rem; top: 50%;
    transform: translateY(-50%); font-size: 6rem; font-weight: 900;
    opacity: .06; letter-spacing: -4px; pointer-events: none;
  }
  .pcm-hero-name { font-size: 1.55rem; font-weight: 700; line-height: 1.2; }
  .pcm-hero-sub  { font-size: .85rem; opacity: .8; margin-top: .2rem; }
  .pcm-meta-grid { display: flex; gap: 1.5rem; flex-wrap: wrap; }
  .pcm-meta-item { text-align: center; }
  .pcm-meta-val  { font-size: 1.25rem; font-weight: 700; display: block; }
  .pcm-meta-lbl  { font-size: .68rem; opacity: .75; text-transform: uppercase; letter-spacing: .05em; }
  .risk-badge-lg {
    padding: .45rem 1rem; border-radius: 999px; font-weight: 700;
    font-size: .85rem; letter-spacing: .04em;
  }
  .risk-HIGH    { background:#fee2e2; color:#dc2626; }
  .risk-MEDIUM  { background:#fef9c3; color:#92400e; }
  .risk-LOW     { background:#dcfce7; color:#166534; }
  .gcpe-badge   { background:rgba(255,255,255,.18); padding:.3rem .7rem; border-radius:6px; font-size:.75rem; font-weight:600; }
  .trend-up   { color:#f87171; }
  .trend-down { color:#4ade80; }
  .trend-flat { color:#94a3b8; }

  /* ── Patient selector ──────────────────────────────────────────── */
  .selector-bar {
    background:#fff; border:1px solid #e2e8f0; border-radius:10px;
    padding:.75rem 1rem; margin-bottom:1.25rem;
    display:flex; align-items:center; gap:1rem; flex-wrap:wrap;
  }

  /* ── Section cards ─────────────────────────────────────────────── */
  .pcm-card {
    background:#fff; border-radius:12px; border:1px solid #e2e8f0;
    box-shadow: 0 1px 3px rgba(0,0,0,.06);
  }
  .pcm-card-header {
    padding:.85rem 1.25rem; border-bottom:1px solid #f1f5f9;
    font-weight:600; font-size:.9rem; display:flex; align-items:center; gap:.5rem;
    color:#0f766e;
  }
  .pcm-card-body { padding:1.25rem; }

  /* ── Vertical timeline ─────────────────────────────────────────── */
  .timeline-wrap { position:relative; padding-left:2rem; }
  .timeline-wrap::before {
    content:''; position:absolute; left:.65rem; top:0; bottom:0;
    width:2px; background:linear-gradient(to bottom,#0d9488,#1d6fa4,#e2e8f0);
  }
  .tl-item { position:relative; margin-bottom:1.25rem; }
  .tl-node {
    position:absolute; left:-2rem; top:.55rem;
    width:20px; height:20px; border-radius:50%;
    border:3px solid #fff; display:flex; align-items:center; justify-content:center;
    font-size:.55rem; font-weight:700; z-index:2;
    box-shadow:0 0 0 2px currentColor;
  }
  .tl-node.HIGH     { background:#dc2626; color:#dc2626; }
  .tl-node.MEDIUM   { background:#d97706; color:#d97706; }
  .tl-node.LOW      { background:#16a34a; color:#16a34a; }
  .tl-node.CRISIS   { background:#7c3aed; color:#7c3aed; animation:pulse-ring 1.5s infinite; }
  @keyframes pulse-ring {
    0%   { box-shadow:0 0 0 2px #7c3aed; }
    70%  { box-shadow:0 0 0 8px rgba(124,58,237,0); }
    100% { box-shadow:0 0 0 2px #7c3aed; }
