{% block scripts %}
<script>
// ── State ────────────────────────────────────────────────────────────────
var bpChartInst   = null;
var riskChartInst = null;
var _data         = null;

// ── Boot ─────────────────────────────────────────────────────────────────
(async function boot() {
  try {
    const pts = await API.get('/api/patients');
    const sel = document.getElementById('patient-select');
    (pts || []).forEach(function(p) {
      const o = document.createElement('option');
      o.value = p.id;
      o.textContent = p.full_name + ' — ' + (p.village || '—') + ' (Age ' + (p.age || '?') + ')';
      sel.appendChild(o);
    });
  } catch(e) {
    console.warn('Patient list error', e);
  }

  document.getElementById('patient-select').addEventListener('change', function() {
    document.getElementById('load-btn').disabled = !this.value;
  });

  document.getElementById('load-btn').addEventListener('click', function() {
    const pid = document.getElementById('patient-select').value;
    if (pid) loadPCM(parseInt(pid));
  });

  // Auto-load from query param
  const qp = new URLSearchParams(window.location.search).get('patient');
  if (qp) {
    const sel = document.getElementById('patient-select');
    sel.value = qp;
    document.getElementById('load-btn').disabled = false;
    loadPCM(parseInt(qp));
  }
}());

// ── Load longitudinal data ────────────────────────────────────────────────
async function loadPCM(patientId) {
  document.getElementById('pcm-empty').style.display    = 'none';
  document.getElementById('pcm-content').style.display  = 'none';
  document.getElementById('pcm-loading').style.display  = 'flex';

  try {
    _data = await API.get('/api/patients/' + patientId + '/longitudinal');
    if (_data.error) { showError(_data.error); return; }
    renderAll(_data);
    document.getElementById('pcm-loading').style.display = 'none';
    document.getElementById('pcm-content').style.display = 'block';
  } catch(e) {
    showError('Failed to load longitudinal data: ' + e.message);
  }
}

function showError(msg) {
  document.getElementById('pcm-loading').style.display = 'none';
  document.getElementById('pcm-empty').style.display   = 'block';
  document.getElementById('pcm-empty').innerHTML =
    '<i class="fa-solid fa-circle-xmark" style="color:#dc2626;font-size:2rem;display:block;margin-bottom:.5rem"></i>' +
    '<div class="fw-semibold text-danger">' + msg + '</div>';
}

// ── Render all sections ───────────────────────────────────────────────────
function renderAll(d) {
  renderHero(d);
  renderStatStrip(d);
  renderNarrative(d);
  renderAlerts(d);
  renderBPChart(d);
  renderRiskChart(d);
  renderTimeline(d);
  renderDeviations(d);
  renderAdherence(d);
  renderPathways(d);
}

// ── 1. Hero card ──────────────────────────────────────────────────────────
function renderHero(d) {
  const p   = d.patient || {};
  const rt  = d.risk_trajectory || {};
  const bp  = d.bp_trend || {};
  const adh = d.adherence || {};
  const visits = d.visits || [];

  document.getElementById('hero-name').textContent = p.full_name || '—';
  document.getElementById('hero-sub').textContent  =
    'Age ' + (p.age || '?') + ' · ' + (p.village || '—') +
    (p.chronic_conditions ? ' · ' + p.chronic_conditions : '');

  // Latest BP + risk from most recent visit
  const last = visits.length ? visits[visits.length - 1] : null;
  const lastRisk  = last ? (last.risk_level || 'LOW') : 'LOW';
  const lastScore = last ? (last.risk_score || 0) : 0;
  const lastBP    = last && last.bp_systolic ? last.bp_systolic + '/' + last.bp_diastolic : '—/—';
  const lastDate  = last ? fmtDate(last.visit_date) : '—';

  const badges = document.getElementById('hero-badges');
  badges.innerHTML =
    '<span class="risk-badge-lg risk-' + lastRisk + '">' + lastRisk + ' RISK</span>' +
    '<span class="gcpe-badge"><i class="fa-solid fa-bolt me-1"></i>GCPE-Driven</span>' +
    '<span class="gcpe-badge"><i class="fa-solid fa-brain me-1"></i>Passive Clinical Memory</span>' +
    trendArrow(rt.direction);

  const meta = document.getElementById('hero-meta');
  meta.innerHTML = [
    metaItem(lastBP + ' mmHg', 'Latest BP'),
    metaItem(lastScore, 'Risk Score'),
    metaItem((adh.adherence_pct || 0) + '%', 'Adherence'),
    metaItem(lastDate, 'Last Visit'),
    metaItem(d.visit_count || visits.length, 'Total Visits'),
  ].join('');
}

function metaItem(val, lbl) {
  return '<div class="pcm-meta-item"><span class="pcm-meta-val">' + val +
    '</span><span class="pcm-meta-lbl">' + lbl + '</span></div>';
}

function trendArrow(dir) {
  if (dir === 'ESCALATING' || dir === 'WORSENING')
    return '<span class="gcpe-badge trend-up"><i class="fa-solid fa-arrow-trend-up me-1"></i>' + dir + '</span>';
  if (dir === 'IMPROVING')
    return '<span class="gcpe-badge trend-down"><i class="fa-solid fa-arrow-trend-down me-1"></i>IMPROVING</span>';
  return '<span class="gcpe-badge trend-flat"><i class="fa-solid fa-minus me-1"></i>' + (dir || 'STABLE') + '</span>';
}

// ── 2. Stat strip ─────────────────────────────────────────────────────────
function renderStatStrip(d) {
  const rt  = d.risk_trajectory || {};
  const ph  = d.pathway_history || {};
  const adh = d.adherence || {};
  document.getElementById('s-visits').textContent = d.visit_count || (d.visits || []).length;
  document.getElementById('s-peak').textContent   = rt.peak || '—';
  document.getElementById('s-crisis').textContent = ph.crisis_events || 0;
  document.getElementById('s-adh').textContent    = (adh.adherence_pct || 0) + '%';
}

// ── 3. Doctor narrative ───────────────────────────────────────────────────
function renderNarrative(d) {
  const box = document.getElementById('pcm-narrative');
  if (d.doctor_narrative) {
    box.innerHTML = '<i class="fa-solid fa-quote-left me-2" style="color:#0d9488;opacity:.5"></i>' +
      d.doctor_narrative +
      '<i class="fa-solid fa-quote-right ms-2" style="color:#0d9488;opacity:.5"></i>';
    box.style.display = 'block';
  }
}

// ── 4. Clinical alerts ────────────────────────────────────────────────────
function renderAlerts(d) {
  const alerts = d.clinical_alerts || [];
  const body   = document.getElementById('alerts-body');
  document.getElementById('alert-count-badge').textContent = alerts.length;

  const icons = [
    'fa-skull-crossbones','fa-triangle-exclamation','fa-exclamation','fa-circle-info'
  ];
  const sevColor = ['#dc2626','#ea580c','#d97706','#64748b'];

  if (!alerts.length) {
    body.innerHTML = '<div class="text-muted small"><i class="fa-solid fa-check-circle text-success me-1"></i>No clinical alerts at this time.</div>';
    return;
  }

  body.innerHTML = alerts.map(function(a, i) {
    const sev = Math.min(i, 3);
    return '<div class="alert-pcm sev-' + sev + '">' +
      '<i class="fa-solid ' + icons[sev] + ' mt-1 flex-shrink-0" style="color:' + sevColor[sev] + '"></i>' +
      '<span>' + a + '</span></div>';
  }).join('');
}

// ── 5. BP Chart ───────────────────────────────────────────────────────────
function renderBPChart(d) {
  const bp    = d.bp_trend || {};
  const reads = bp.readings || [];
  const dates = bp.dates    || reads.map(function(_,i){ return 'V'+(i+1); });

  document.getElementById('bp-dir-label').textContent = bp.direction || '';

  if (bpChartInst) { bpChartInst.destroy(); bpChartInst = null; }
  if (!reads.length) return;

  const ctx = document.getElementById('bpChart').getContext('2d');
  bpChartInst = new Chart(ctx, {
    type: 'line',
    data: {
      labels: dates,
      datasets: [
        {
          label: 'Systolic BP (mmHg)',
          data: reads,
          borderColor: '#0d9488',
          backgroundColor: 'rgba(13,148,136,.08)',
          borderWidth: 2.5,
          pointRadius: 5,
          pointBackgroundColor: reads.map(function(v){
            return v >= 180 ? '#dc2626' : v >= 140 ? '#d97706' : '#16a34a';
          }),
          tension: 0.35,
          fill: true,
        },
        {
          label: 'Crisis Threshold (180)',
          data: Array(reads.length).fill(180),
          borderColor: '#dc2626',
          borderDash: [6,4],
          borderWidth: 1.5,
          pointRadius: 0,
          fill: false,
        },
        {
          label: 'Stage 1 Threshold (140)',
          data: Array(reads.length).fill(140),
          borderColor: '#d97706',
          borderDash: [4,3],
          borderWidth: 1.5,
          pointRadius: 0,
          fill: false,
        },
      ]
    },
    options: {
      responsive: true,
      animation: { duration: 800 },
      plugins: {
        legend: { position: 'bottom', labels: { boxWidth: 12, font: { size: 11 } } },
        tooltip: {
          callbacks: {
            label: function(ctx) {
              if (ctx.datasetIndex === 0) {
                var v = ctx.raw;
                var zone = v >= 180 ? '🔴 CRISIS' : v >= 140 ? '🟡 STAGE 1' : '🟢 NORMAL';
                return ' ' + v + ' mmHg — ' + zone;
              }
              return ctx.dataset.label;
            }
          }
        }
      },
      scales: {
        y: {
          min: Math.max(60, Math.min.apply(null,reads) - 20),
          max: Math.max.apply(null,reads) + 20,
          grid: { color: '#f1f5f9' },
          ticks: { font: { size: 11 } }
        },
        x: { grid: { display: false }, ticks: { font: { size: 10 }, maxRotation: 45 } }
      }
    }
  });
}

// ── 6. Risk Chart ─────────────────────────────────────────────────────────
function renderRiskChart(d) {
  const rt     = d.risk_trajectory || {};
  const scores = rt.scores || [];
  const dates  = rt.dates  || scores.map(function(_,i){ return 'V'+(i+1); });

  document.getElementById('risk-dir-label').textContent = rt.direction || '';

  if (riskChartInst) { riskChartInst.destroy(); riskChartInst = null; }
  if (!scores.length) return;

  const ctx = document.getElementById('riskChart').getContext('2d');
  riskChartInst = new Chart(ctx, {
    type: 'line',
    data: {
      labels: dates,
      datasets: [
        {
          label: 'Risk Score',
          data: scores,
          borderColor: function(ctx) { return '#7c3aed'; },
          backgroundColor: 'rgba(124,58,237,.07)',
          borderWidth: 2.5,
          pointRadius: 5,
          pointBackgroundColor: scores.map(function(v){
            return v >= 70 ? '#dc2626' : v >= 40 ? '#d97706' : '#16a34a';
          }),
          tension: 0.35,
          fill: true,
        },
        {
          label: 'High Risk (70)',
          data: Array(scores.length).fill(70),
          borderColor: '#dc2626',
          borderDash: [6,4],
          borderWidth: 1.5,
          pointRadius: 0,
          fill: false,
        },
        {
          label: 'Medium Risk (40)',
          data: Array(scores.length).fill(40),
          borderColor: '#d97706',
          borderDash: [4,3],
          borderWidth: 1.5,
          pointRadius: 0,
          fill: false,
        }
      ]
    },
    options: {
      responsive: true,
      animation: { duration: 900, easing: 'easeInOutQuart' },
      plugins: {
        legend: { position: 'bottom', labels: { boxWidth: 12, font: { size: 11 } } },
        tooltip: {
          callbacks: {
            label: function(ctx) {
              if (ctx.datasetIndex === 0) {
                var v = ctx.raw;
                var zone = v >= 70 ? '🔴 HIGH' : v >= 40 ? '🟡 MEDIUM' : '🟢 LOW';
                return ' Score: ' + v + ' — ' + zone;
              }
              return ctx.dataset.label;
            }
          }
        }
      },
      scales: {
        y: {
          min: 0, max: 100,
          grid: { color: '#f1f5f9' },
          ticks: { font: { size: 11 } }
        },
        x: { grid: { display: false }, ticks: { font: { size: 10 }, maxRotation: 45 } }
      }
    }
  });
}

// ── 7. Vertical timeline ──────────────────────────────────────────────────
function renderTimeline(d) {
  const visits  = (d.visits || []).slice().reverse(); // newest first
  const body    = document.getElementById('timeline-body');
  const ph      = d.pathway_history || {};
  const crisisSet = new Set(['hypertensive_crisis','crisis_escalation']);

  document.getElementById('tl-visit-count').textContent = visits.length + ' visits';

  if (!visits.length) {
    body.innerHTML = '<div class="text-muted small">No visits recorded.</div>';
    return;
  }

  body.innerHTML = visits.map(function(v, idx) {
    const pathways = ((v.gcpe_data || {}).pathways || []);
    const isCrisis = pathways.some(function(p){ return crisisSet.has(p); }) ||
                     parseInt(v.bp_systolic||0) >= 180;
    const level    = v.risk_level || 'LOW';
    const nodeClass = isCrisis ? 'CRISIS' : level;

    const pathwayBadges = pathways.map(function(p) {
      var cls = crisisSet.has(p) ? 'badge-alert' : 'badge-pathway';
      return '<span class="tl-badge ' + cls + '">' + p.replace(/_/g,' ') + '</span>';
    }).join('');

    const symptomBadges = [
      v.chest_pain ? '<span class="tl-badge badge-alert">chest pain</span>' : '',
      v.dizziness  ? '<span class="tl-badge badge-warn">dizziness</span>'   : '',
      v.medicine_missed ? '<span class="tl-badge badge-warn">meds missed</span>' : '',
      !v.chest_pain && !v.dizziness && !v.medicine_missed ?
        '<span class="tl-badge badge-ok">no symptoms</span>' : '',
    ].join('');

    const cardClass = isCrisis ? 'crisis-event' :
                      (level === 'HIGH' ? 'escalation-event' : '');

    return '<div class="tl-item">' +
      '<div class="tl-node ' + nodeClass + '"></div>' +
      '<div class="tl-card ' + cardClass + '">' +
        '<div class="tl-date"><i class="fa-regular fa-calendar me-1"></i>' + fmtDate(v.visit_date) +
          (idx === 0 ? ' <span class="badge bg-teal" style="background:#0d9488;font-size:.6rem;">LATEST</span>' : '') +
        '</div>' +
        '<div class="d-flex align-items-center gap-2 mb-1">' +
          '<span class="tl-bp">' + (v.bp_systolic||'—') + '/' + (v.bp_diastolic||'—') + '</span>' +
          '<span class="text-muted small">mmHg</span>' +
          '<span class="ms-auto badge risk-' + level + '" style="font-size:.65rem;">' +
            'Risk ' + (v.risk_score||0) +
          '</span>' +
        '</div>' +
        (v.pulse ? '<div class="text-muted" style="font-size:.75rem;"><i class="fa-solid fa-heart-pulse me-1"></i>Pulse: ' + v.pulse + ' bpm</div>' : '') +
        '<div class="tl-badges">' + symptomBadges + pathwayBadges + '</div>' +
        (v.notes ? '<div class="text-muted mt-1" style="font-size:.73rem;font-style:italic;">' + v.notes + '</div>' : '') +
      '</div>' +
    '</div>';
  }).join('');
}

// ── 8. First deviations ───────────────────────────────────────────────────
function renderDeviations(d) {
  const devs = d.first_deviations || [];
  const body = document.getElementById('deviations-body');

  if (!devs.length) {
    body.innerHTML = '<div class="col-12 text-muted small"><i class="fa-solid fa-check-circle text-success me-1"></i>No significant deviations detected.</div>';
    return;
  }

  const icons = {
    FIRST_ABNORMAL_BP:        'fa-heart-crack',
    FIRST_HYPERTENSIVE_CRISIS:'fa-skull-crossbones',
    FIRST_CHEST_PAIN:         'fa-lungs',
    FIRST_DIZZINESS:          'fa-person-falling',
    FIRST_MEDICATION_MISS:    'fa-pills',
    FIRST_CRISIS_ESCALATION:  'fa-truck-medical',
    FIRST_TACHYCARDIA:        'fa-heart-pulse',
  };
  const sevColors = {
    CRITICAL:'#dc2626', HIGH:'#ea580c', MEDIUM:'#d97706', LOW:'#16a34a'
  };

  body.innerHTML = devs.map(function(dev) {
    var icon  = icons[dev.type] || 'fa-flag';
    var color = sevColors[dev.severity] || '#64748b';
    var label = (dev.type || '').replace(/_/g,' ');
    return '<div class="col-md-6"><div class="dev-card dev-' + dev.severity + '">' +
      '<div class="dev-type d-flex align-items-center gap-1" style="color:' + color + '">' +
        '<i class="fa-solid ' + icon + '"></i> ' + label +
        ' <span class="ms-auto badge" style="background:' + color + '22;color:' + color + ';font-size:.6rem;">' + dev.severity + '</span>' +
      '</div>' +
      '<div class="dev-date"><i class="fa-regular fa-calendar me-1"></i>' + (dev.date || '—') + '</div>' +
      '<div>' + (dev.description || '') + '</div>' +
      (dev.value ? '<div class="mt-1 fw-bold" style="color:' + color + ';">' + dev.value + '</div>' : '') +
    '</div></div>';
  }).join('');
}

// ── 9. Adherence ──────────────────────────────────────────────────────────
function renderAdherence(d) {
  const adh  = d.adherence || {};
  const body = document.getElementById('adherence-body');
  const pct  = adh.adherence_pct || 0;
  const cons = adh.current_consecutive_miss || 0;
  const maxC = adh.max_consecutive_miss || 0;
  const reasons = adh.missed_reasons || {};

  const barColor = pct >= 80 ? '#16a34a' : pct >= 60 ? '#d97706' : '#dc2626';
  const trendBadge = {
    'GOOD':'badge-ok','IMPROVING':'badge-ok',
    'STABLE':'badge-warn','WORSENING':'badge-alert','NO_DATA':'badge-warn'
  }[adh.trend] || 'badge-warn';

  const reasonsHtml = Object.keys(reasons).length ?
    '<div class="mt-2"><div class="small fw-semibold text-muted mb-1">Missed Reasons</div>' +
    Object.entries(reasons).map(function(kv){
      return '<div class="d-flex justify-content-between small mb-1">' +
        '<span>' + kv[0] + '</span>' +
        '<span class="badge badge-warn">' + kv[1] + '×</span></div>';
    }).join('') + '</div>' : '';

  body.innerHTML =
    '<div class="d-flex justify-content-between align-items-center mb-1">' +
      '<span class="fw-semibold" style="font-size:.85rem;">Overall Adherence</span>' +
      '<span class="fw-bold" style="color:' + barColor + ';font-size:1.2rem;">' + pct + '%</span>' +
    '</div>' +
    '<div class="adh-bar-wrap">' +
      '<div class="adh-bar-fill" style="width:' + pct + '%;background:' + barColor + ';"></div>' +
    '</div>' +
    '<div class="d-flex gap-1 mt-2 flex-wrap">' +
      '<span class="tl-badge ' + trendBadge + '">Trend: ' + (adh.trend || '—') + '</span>' +
      (cons >= 1 ? '<span class="tl-badge badge-alert">Current: ' + cons + ' missed streak</span>' : '') +
      (maxC > 0  ? '<span class="tl-badge badge-warn">Max streak: ' + maxC + '</span>' : '') +
    '</div>' +
    (adh.narrative ? '<div class="mt-2 small text-muted">' + adh.narrative + '</div>' : '') +
    reasonsHtml;
}

// ── 10. Pathways ──────────────────────────────────────────────────────────
function renderPathways(d) {
  const ph    = d.pathway_history || {};
  const paths = ph.pathways || {};
  const body  = document.getElementById('pathway-body');

  const crisisPaths = new Set(['hypertensive_crisis','crisis_escalation']);

  const keys = Object.keys(paths);
  if (!keys.length) {
    body.innerHTML = '<div class="text-muted small">No GCPE pathways triggered across visit history.</div>';
    return;
  }

  const pills = keys.sort(function(a,b){ return paths[b].count - paths[a].count; }).map(function(k) {
    var p   = paths[k];
    var cls = crisisPaths.has(k) ? 'escalation' : (k.indexOf('urgent') !== -1 ? 'crisis' : '');
    return '<span class="pathway-pill ' + cls + '">' +
      '<i class="fa-solid fa-route" style="font-size:.65rem"></i>' +
      k.replace(/_/g,' ') +
      '<span class="badge ms-1" style="background:rgba(0,0,0,.12);font-size:.6rem;">' + p.count + '×</span>' +
    '</span>';
  }).join('');

  const summary = [
    '<div class="mb-2">' + pills + '</div>',
    '<div class="d-flex gap-3 mt-2 small text-muted">',
    '<span><strong>' + (ph.total_pathway_events||0) + '</strong> total events</span>',
    '<span><strong>' + (ph.crisis_events||0) + '</strong> crisis events</span>',
    '<span><strong>' + (ph.escalation_events||0) + '</strong> escalations</span>',
    '</div>',
  ].join('');

  body.innerHTML = summary;
}

// ── Helpers ───────────────────────────────────────────────────────────────
function fmtDate(dt) {
  if (!dt) return '—';
  try {
    return new Date(dt).toLocaleDateString('en-IN', { day:'numeric', month:'short', year:'numeric' });
  } catch(e) { return String(dt).slice(0,10); }
}
</script>
{% endblock %}

