  }

  /* ── Blockchain flow ─────────────────────────────────────────── */
  .chain-flow {
    display:flex; flex-direction:column; gap:0;
    position:relative;
  }
  .chain-item { position:relative; }

  .block-card-bc {
    background:#fff; border:2px solid #e2e8f0; border-radius:12px;
