  .block-card-bc.genesis { border-color:#7c3aed; background:#faf5ff; }
  .block-card-bc.tampered-visual { border-color:#dc2626 !important; background:#fff5f5;
    animation: shake .4s ease; }
  @keyframes shake {
    0%,100%{transform:translateX(0)}
    20%{transform:translateX(-4px)}
    40%{transform:translateX(4px)}
    60%{transform:translateX(-3px)}
    80%{transform:translateX(3px)}
  }

  .chain-connector {
    display:flex; align-items:center; justify-content:center;
    height:36px; position:relative; z-index:1;
  }
  .chain-connector::before {
    content:''; position:absolute; left:50%; top:0; bottom:0;
    width:2px; background:#0d9488; transform:translateX(-50%);
