  }
  .chain-connector.broken::before { background:#dc2626; }
  .chain-arrow {
    width:28px; height:28px; border-radius:50%;
    background:#0d9488; color:#fff; display:flex; align-items:center;
    justify-content:center; font-size:.7rem; z-index:2; position:relative;
