  }
  .block-index-badge {
    font-size:.75rem; font-weight:700; padding:.3rem .7rem;
    border-radius:6px; font-family:'Courier New',monospace;
  }
  .hash-field {
    font-family:'Courier New',monospace; font-size:.7rem; color:#475569;
    word-break:break-all; background:#f8fafc; border-radius:6px;
