    transition:background .3s, color .3s;
  }
  .hash-field.pow-valid { color:#0f766e; background:#f0fdf4; }
  .hash-field.pow-invalid { color:#dc2626; background:#fff5f5; }
  .hash-field.tampered-hash { color:#dc2626; background:#fff5f5;
    text-decoration:line-through; }

  .sig-badge {
    display:inline-flex; align-items:center; gap:.3rem;
