{% block scripts %}
<script>
var _chain       = [];
var _tampered    = false;
var _tamperIndex = -1;
var _miningTimer = null;

// ── Boot ─────────────────────────────────────────────────────────────
loadAll();

async function loadAll() {
  try {
    var res = await Promise.all([
      API.get('/api/blockchain/chain'),
      API.get('/api/blockchain/stats'),
    ]);
    var chainData = res[0];
    var stats     = res[1];

    _chain    = (chainData.chain || []).slice().sort(function(a,b){ return a.block_index - b.block_index; });
    _tampered = false;
    _tamperIndex = -1;

    renderStats(stats);
    renderChain(_chain, false);
    await verifyAndRender();
  } catch(e) {
    console.error('Blockchain load error', e);
  }
}

// ── Stats strip ───────────────────────────────────────────────────────
function renderStats(s) {
  document.getElementById('s-total').textContent   = s.total_blocks || 0;
  document.getElementById('s-latest').textContent  = s.latest_index != null ? '#' + s.latest_index : '—';
  document.getElementById('s-pow').textContent      = '0000…';

  if (s.genesis_time) {
    var d = new Date(s.genesis_time * 1000);
    document.getElementById('s-genesis').textContent =
      d.toLocaleDateString('en-IN', {day:'numeric',month:'short',year:'numeric'});
  }
}

// ── Chain flow render ─────────────────────────────────────────────────
function renderChain(chain, tamperIdx) {
  var container = document.getElementById('chain-flow-container');
  document.getElementById('block-count-badge').textContent = chain.length + ' block' + (chain.length !== 1 ? 's' : '');

  if (!chain.length) {
    container.innerHTML = '<div class="text-center text-muted py-4"><i class="fa-solid fa-cube fa-2x mb-2 d-block opacity-25"></i>No blocks yet. ASHA visits will mine blocks here.</div>';
    renderSigPanel([], false);
    return;
  }

  var html = '';
  var reversedChain = chain.slice().reverse();

  reversedChain.forEach(function(b, idx) {
    var isTampered  = (b.block_index === tamperIdx);
    var isGenesis   = (b.block_index === 0);
    var isInvalid   = (!b.is_valid || isTampered);
    var isLastItem  = (idx === reversedChain.length - 1);

    var cardClass = isGenesis ? 'genesis' : (isTampered ? 'tampered-visual' : (isInvalid ? 'invalid' : ''));
    var hashCls   = isTampered ? 'tampered-hash' : (b.current_hash && b.current_hash.startsWith('0000') ? 'pow-valid' : '');

    var powOk  = b.current_hash && b.current_hash.startsWith('0000');
    var sigBadge = b.signature
      ? (isTampered ? '<span class="sig-badge sig-bad"><i class="fa-solid fa-xmark"></i>Signature Invalid</span>'
                    : '<span class="sig-badge sig-ok"><i class="fa-solid fa-check"></i>ECDSA Verified</span>')
      : '<span class="sig-badge sig-na"><i class="fa-regular fa-circle"></i>No Signature</span>';

    var visitFingerprint = b.visit_hash
      ? '<div class="mt-2"><div class="small text-muted fw-semibold mb-1">Visit Data Fingerprint</div><div class="hash-field">' + b.visit_hash + '</div></div>'
      : '';

    var tamperNote = isTampered
      ? '<span class="tamper-note ms-2"><i class="fa-solid fa-triangle-exclamation me-1"></i>DATA MODIFIED</span>'
      : '';

    var chainBroken = (isTampered || (_tampered && b.block_index > tamperIdx));

    html += '<div class="chain-item">';
    html += '<div class="block-card-bc ' + cardClass + '">';
    html += '  <div class="block-header">';
    html += '    <span class="block-index-badge ' + (isGenesis ? 'bg-secondary text-white' : 'text-secondary') + '" style="' + (isGenesis ? '' : 'background:#f1f5f9;') + '">#' + b.block_index + '</span>';
    html += isGenesis
      ? '<span style="font-size:.72rem;font-weight:600;background:#ede9fe;color:#5b21b6;padding:.2rem .5rem;border-radius:4px;"><i class="fa-solid fa-star me-1"></i>Genesis Block</span>'
      : '<span style="font-size:.72rem;font-weight:600;background:#eff6ff;color:#1e40af;padding:.2rem .5rem;border-radius:4px;"><i class="fa-solid fa-notes-medical me-1"></i>Visit Block</span>';
    html += tamperNote;
    html += '    <span class="ms-auto"><span class="pow-badge ' + (powOk && !isTampered ? 'pow-ok' : 'pow-bad') + '"><i class="fa-solid fa-' + (powOk && !isTampered ? 'check' : 'xmark') + '"></i>PoW</span></span>';
    html += '    ' + sigBadge;
    html += '  </div>';

    html += '  <div class="row g-2 small">';
    html += '    <div class="col-6"><div class="text-muted">Block Index</div><div class="fw-semibold">#' + b.block_index + '</div></div>';
    html += '    <div class="col-6"><div class="text-muted">Timestamp</div><div class="fw-semibold">' + fmtTs(b.timestamp) + '</div></div>';
    html += '    <div class="col-6"><div class="text-muted">Nonce (PoW Iterations)</div><div class="fw-semibold" style="font-family:monospace;">' + (b.nonce != null ? Number(b.nonce).toLocaleString() : '—') + '</div></div>';
    html += '    <div class="col-6"><div class="text-muted">Validity</div><div class="fw-semibold ' + (isInvalid ? 'text-danger' : 'text-success') + '">' + (isTampered ? '✗ TAMPERED' : (b.is_valid ? '✓ Valid' : '✗ Invalid')) + '</div></div>';
    html += '    <div class="col-12"><div class="small text-muted fw-semibold mb-1">Current Hash</div><div class="hash-field ' + hashCls + '">' + (isTampered ? corruptHash(b.current_hash) : (b.current_hash || '—')) + '</div></div>';
    html += '    <div class="col-12"><div class="small text-muted fw-semibold mb-1">Previous Hash</div><div class="hash-field">' + (b.previous_hash || '—') + '</div></div>';
    html += visitFingerprint;
    html += '  </div>';
    html += '</div>';

    if (!isLastItem) {
      var broken = _tampered && (b.block_index >= (_tamperIndex > -1 ? _tamperIndex : 9999) || (isTampered));
      var connBroken = _tampered;
      html += '<div class="chain-connector ' + (connBroken ? 'broken' : '') + '">';
      html += '  <div class="chain-arrow ' + (connBroken ? 'broken' : '') + '"><i class="fa-solid fa-arrow-down" style="font-size:.55rem"></i></div>';
      html += '</div>';
    }

    html += '</div>';
  });

  container.innerHTML = html;
  renderSigPanel(chain, _tampered);
}

// ── Signature verification panel ──────────────────────────────────────
function renderSigPanel(chain, tampered) {
  var panel = document.getElementById('sig-verify-panel');
  var signed = chain.filter(function(b){ return !!b.signature; });
  var total  = chain.length;

  if (!total) {
    panel.innerHTML = '<div class="text-muted small">No blocks to verify.</div>';
    return;
  }

  var overallOk = !tampered;

  panel.innerHTML = [
    '<div class="d-flex align-items-center gap-2 mb-2">',
    '  <i class="fa-solid fa-' + (overallOk ? 'shield-check' : 'shield-xmark') + ' fa-lg" style="color:' + (overallOk ? '#0f766e' : '#dc2626') + '"></i>',
    '  <div>',
    '    <div class="fw-bold small" style="color:' + (overallOk ? '#0f766e' : '#dc2626') + ';">' + (overallOk ? 'Cryptographic Integrity: CONFIRMED' : 'Cryptographic Integrity: FAILED') + '</div>',
    '    <div class="text-muted" style="font-size:.7rem;">SHA-256 + ECDSA + Proof-of-Work</div>',
    '  </div>',
    '</div>',
    '<div class="d-flex flex-column gap-1 mt-2">',
    row('fa-hashtag', 'SHA-256 Chain Hash', total + '/' + total + ' linked', overallOk),
    row('fa-key', 'ECDSA Signatures', signed.length + ' signed blocks', overallOk && signed.length > 0),
    row('fa-hammer', 'Proof-of-Work', 'Difficulty 4 (0000… prefix)', overallOk),
    row('fa-link', 'Hash Continuity', 'prev_hash → curr_hash verified', overallOk),
    '</div>',
    tampered ? '<div class="mt-2 p-2 rounded" style="background:#fff5f5;border:1px solid #fca5a5;font-size:.75rem;color:#991b1b;"><i class="fa-solid fa-triangle-exclamation me-1"></i>Tamper simulation active. Chain integrity is <strong>broken</strong>.</div>' : '',
  ].join('');
}

function row(icon, label, val, ok) {
  return '<div class="d-flex justify-content-between align-items-center py-1" style="border-bottom:1px solid #f1f5f9;font-size:.78rem;">' +
    '<span><i class="fa-solid ' + icon + ' me-1 text-muted" style="width:14px"></i>' + label + '</span>' +
    '<span style="color:' + (ok ? '#0f766e' : '#dc2626') + ';font-weight:600;">' + (ok ? '✓' : '✗') + ' ' + val + '</span>' +
  '</div>';
}

// ── Verify banner ─────────────────────────────────────────────────────
async function verifyAndRender() {
  var banner = document.getElementById('verify-banner');
  try {
    var result = await API.get('/api/blockchain/verify');
    var valid  = _tampered ? false : result.valid;
    var total  = result.block_results ? result.block_results.length : 0;
    var validN = _tampered ? Math.max(0, total - 1) : (result.block_results || []).filter(function(r){ return r.valid; }).length;
    var pct    = total ? Math.round((validN / total) * 100) : 100;

    setBanner(valid);
    document.getElementById('bs-blocks').textContent    = total;
    document.getElementById('bs-valid').textContent     = validN;
    document.getElementById('bs-integrity').textContent = pct + '%';
  } catch(e) {
    setBanner(true); // assume ok if no data
    document.getElementById('bs-blocks').textContent    = _chain.length;
    document.getElementById('bs-valid').textContent     = _chain.length;
    document.getElementById('bs-integrity').textContent = _chain.length ? '100%' : '—';
  }
}

function setBanner(valid) {
  var banner = document.getElementById('verify-banner');
  var icon   = document.getElementById('banner-icon');
  var title  = document.getElementById('banner-title');
  var sub    = document.getElementById('banner-sub');
  var failBar = document.getElementById('integrity-fail-bar');

  if (valid) {
    banner.className = 'verify-banner state-verified';
    icon.innerHTML   = '<i class="fa-solid fa-shield-check"></i>';
    title.textContent = 'CHAIN VERIFIED';
    sub.textContent   = 'All blocks cryptographically intact — no tampering detected';
    failBar.classList.remove('show');
  } else {
    banner.className  = 'verify-banner state-tampered';
    icon.innerHTML    = '<i class="fa-solid fa-shield-xmark"></i>';
    title.textContent = 'INTEGRITY FAILURE DETECTED';
    sub.textContent   = 'Chain tampering detected — one or more blocks have been modified';
    failBar.classList.add('show');
  }
}

// ── Tamper simulation ─────────────────────────────────────────────────
function simulateTamper() {
  if (!_chain.length) { alert('No blocks to tamper with.'); return; }

  _tampered    = true;
  _tamperIndex = _chain.length > 1 ? _chain[Math.floor(_chain.length / 2)].block_index : _chain[0].block_index;

  document.getElementById('tamper-btn').classList.add('d-none');
  document.getElementById('restore-btn').classList.remove('d-none');

  renderChain(_chain, _tamperIndex);
  setBanner(false);
  document.getElementById('bs-integrity').textContent = Math.round((_chain.length > 1 ? (_chain.length - 1) / _chain.length : 0) * 100) + '%';
  document.getElementById('bs-valid').textContent     = Math.max(0, _chain.length - 1);
}

function restoreChain() {
  _tampered    = false;
  _tamperIndex = -1;

  document.getElementById('tamper-btn').classList.remove('d-none');
  document.getElementById('restore-btn').classList.add('d-none');
  document.getElementById('integrity-fail-bar').classList.remove('show');

  renderChain(_chain, -1);
  verifyAndRender();
}

function corruptHash(hash) {
  if (!hash) return 'CORRUPTED';
  var arr = hash.split('');
  for (var i = 4; i < 12; i++) {
    arr[i] = Math.floor(Math.random() * 16).toString(16);
  }
  return arr.join('') + ' <span class="tamper-note">MODIFIED</span>';
}

// ── Mining simulator ──────────────────────────────────────────────────
function runMiningDemo() {
  if (_miningTimer) { clearInterval(_miningTimer); _miningTimer = null; }

  var log     = document.getElementById('mining-log');
  var nonce   = 0;
  var target  = '0000';
  var data    = 'AarogyaNet|Patient:' + (Math.floor(Math.random()*999)+1) + '|BP:' + (120+Math.floor(Math.random()*60)) + '|Risk:' + (Math.floor(Math.random()*80)+20);
  var found   = false;
  var maxIter = 1200 + Math.floor(Math.random() * 3000);

  log.innerHTML = '<div style="color:#38bdf8;margin-bottom:.5rem;">⬡ Initiating Proof-of-Work mining…</div>' +
    '<div style="color:#94a3b8;margin-bottom:.5rem;">Data: <span style="color:#fbbf24;">' + data + '</span></div>';

  _miningTimer = setInterval(function() {
    if (found) return;
    nonce++;

    var fakeHash = genFakeHash(nonce);
    var isValid  = (nonce >= maxIter) || fakeHash.startsWith('0000');

    if (nonce % 80 === 0 || isValid) {
      var line = document.createElement('div');
      if (isValid) {
        line.innerHTML =
          '<div class="mining-accepted" style="margin-top:.5rem;">✓ BLOCK ACCEPTED!</div>' +
          '<div style="color:#94a3b8;">Nonce: <span class="mining-nonce">' + nonce.toLocaleString() + '</span></div>' +
          '<div style="color:#94a3b8;">Hash:  <span class="mining-hash">' + '0000' + fakeHash.slice(4) + '</span></div>' +
          '<div style="color:#4ade80;margin-top:.3rem;">⬡ Proof-of-Work satisfied. Block sealed into chain.</div>';
        found = true;
        clearInterval(_miningTimer);
        _miningTimer = null;
      } else {
        line.innerHTML =
          'nonce=<span class="mining-nonce">' + nonce.toLocaleString() + '</span> ' +
          'hash=<span class="mining-hash">' + fakeHash.slice(0,16) + '…</span> ' +
          '<span style="color:#ef4444;">✗</span>';
      }
      log.appendChild(line);
      log.scrollTop = log.scrollHeight;
      if (log.children.length > 18) log.removeChild(log.children[1]);
    }
  }, 60);
}

function genFakeHash(nonce) {
  var chars = '0123456789abcdef';
  var h = '';
  var seed = nonce * 2654435761;
  for (var i = 0; i < 64; i++) {
    h += chars[(seed >> (i % 28)) & 15];
    seed = (seed * 1664525 + 1013904223) >>> 0;
  }
  return h;
}

// ── Helpers ───────────────────────────────────────────────────────────
function fmtTs(ts) {
  if (!ts) return '—';
  try {
    return new Date(ts * 1000).toLocaleString('en-IN', {
      day:'numeric', month:'short', year:'numeric',
      hour:'2-digit', minute:'2-digit'
    });
  } catch(e) { return String(ts); }
}
</script>
